import{_ as t,c as s,o as l,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"易附錄纂注卷十二","description":"易附錄纂注 - 易附錄纂注卷十二","frontmatter":{"title":"易附錄纂注卷十二","description":"易附錄纂注 - 易附錄纂注卷十二"},"headers":[],"relativePath":"classics/yifulu-zuanzhu/013.md","filePath":"classics/yifulu-zuanzhu/013.md"}'),r={name:"classics/yifulu-zuanzhu/013.md"};function i(c,a,o,u,d,p){return l(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"易附錄纂注卷十二",tabindex:"-1"},[n("易附錄纂注卷十二 "),e("a",{class:"header-anchor",href:"#易附錄纂注卷十二","aria-label":"Permalink to “易附錄纂注卷十二”"},"​")],-1),e("p",null,"欽定四庫全書",-1),e("p",null,"元胡一桂撰總論雜卦 雜卦反對之義，只是反覆，則其吉凶、禍福、動靜、剛柔皆相反了。答虞大中。",-1),e("p",null,"乾剛坤柔。附錄。 剛柔雖各有所偏，必相錯而後得中。然在乾、坤二卦之全體，當剛而剛，當柔而柔，則不待相錯而不害其全矣。其爻位之無過不及者，如乾、坤之二五，亦不待相錯而不害其為中矣。陰陽變化，而太極之妙無不在焉，於此蓋可見也。今謂「乾剛坤柔」，便有所偏，恐於二卦之彖及二五之爻有不通者。答虞大中。 「比樂師憂」，臨、觀之義，或與或求。 以我臨物曰「與」，物來觀我曰「求」。或曰：二卦互有「與」「求」之義。 附錄。 「臨」、觀更有「與」「求」之義。「臨」，以二陽言之，則二陽可以臨上四陰。以卦中爻言之，則六五、上六又以上而臨下。「觀」，自下而觀上則為觀，是平聲；自上而為物之觀。是去聲。道夫。 屯見而不失其居，蒙雜而著。 「屯」，震遇坎，震動故見坎險不行也。「蒙」，坎遇艮，坎幽昧，艮光明也。或曰「屯」以初言，「蒙」以二言。 纂注：蔡氏曰：屯，物之始生，故見主初也未得位而利居貞，故不失其居。蒙然而生，故「雜」。二為蒙主，而能治之使明，故著。 震，起也；「艮」，止也。損、益，盛衰之始也。纂注：蔡氏曰：「震陽起於下，艮陽止於上。損者，盛之始，益者，衰之始。」 大畜，時也；無妄，災也。 止健者，時有適然。無妄而災自外至。 纂注：蔡氏曰：「剛健者難畜，當剛止之時，故能畜，莫非災也。無妄之災，乃所謂災也。」 萃聚而升不來也。纂注：蔡氏曰：「澤聚而下，木升而上。」 謙輕而豫怠也。附錄：謙輕是自謙抑，不自尊重。道夫輕是自卑小之義，說豫之極，便放倒了，如上文「冥豫」是也。去偽。 噬嗑，食也；賁，無色也， 白受採。 纂注：蔡氏曰：「頤中有物，故食。賁則其色不常，故無色。」 兌見而巽伏也。 兌陰外見，巽陰內伏。 隨，無故也，蠱則飭也。 隨前無故，蠱後當飭。 剝，爛也；復，反也。纂注：蔡氏曰：「剝則陽爛，復則陽反。」 晉，晝也；明夷，誅也。 誅，傷也。 纂注：蔡氏曰：「晉離在上而明著，夷，離在下而明傷。」 井通，而困相遇也。 剛柔相遇而剛見揜也。 纂注：蔡氏曰：「井往而不窮，故為通。」困，剛掩也，剛與柔相遇也。 鹹，速也；恆，久也。 鹹，速；恆，久。 纂注：蔡氏曰：「有感則應，故速；常，故能久。」 渙，離也；節，止也。纂注：蔡氏曰：「風散水，故離，澤防水故止。」 解，緩也；蹇，難也。附錄：散緩意，如縱弛之類。道夫、 睽，外也；家人，內也；否、泰，反其類也。大壯則止，遁則退也。 止謂不退。 纂注：蔡氏曰：「大壯陰止，遁陽退。」徐氏曰：「雜卦言止者三：艮，止也，謂陽升於上，止而不進，天之道也。節，止也，謂有所限節而遏止之，人之力也。大壯則止，謂四陽方壯，止而不退，亦天道也。」 大有，眾也；同人，親也。革，去故也；鼎，取新也。小過，過也；中孚，信也。纂注：蔡氏曰：「莫非過也，小過之過，乃所謂過也。小者能過，豈常理哉！莫非信也，中孚之信，乃所謂信也。信出於中，豈要約之所能致哉！」 豐，多故也；親寡，旅也。 既明且動，其故多矣。 離上而坎下也。 火炎上，水潤下。 小畜，寡也；履，不處也。 不處，行進之義。 需，不進也；訟，不親也；大過，顛也。纂注：徐氏曰：「本末弱，故顛。」 姤，遇也，柔遇剛也。漸，女歸待男行也。附錄：女待男而行，所以為漸。淵。 頤，養正也；既濟，定也。纂注：蔡氏曰：「六位皆當，故定。」 歸妹，女之終也；未濟，男之窮也。附錄：伊川說未濟男之窮，為三陽失位，以為斯義也得之成都隱者。見張欽夫說伊川之在涪也，一日讀易，有刳桶人以此問伊川，伊川不能答。其人云：「三陽失位，故伊川記之。」不知此語火珠林上已有。蓋伊川未嘗看雜書，所以被他說動了。淵。 夬，決也，剛決柔也。君子道長，小人道憂也。 自姤以下，卦不反對，或疑其錯簡，今以韻協之，又似非誤，未詳何義。 纂注。 蔡氏曰：「自姤以下有亂簡。」按雜卦例皆反對協韻為序，今以其例改正。大過，顛也；頤，養正也；既濟，定也。未濟，男之窮也。歸妹，女之終也。漸，女歸待男行也。姤，遇也，柔遇剛也。夬，決也，剛決柔也，君子道長，小人道憂也。愚謂雜卦以乾為首，不終之以他卦，而必終之以夬者，蓋夬以五陽決一陰，決去一陰，則復為乾矣，故曰「君子道長，小人道憂也」。易為君子謀，大哉言矣！ 易附錄纂注卷十二。",-1)])])}const _=t(r,[["render",i]]);export{m as __pageData,_ as default};
